"""Visit records."""


class Visit:
    def __init__(self, page, minutes):
        self.page = page
        self.minutes = minutes

    def __repr__(self):
        return "Visit(%r, %r)" % (self.page, self.minutes)


ROWS = [('shop', 36), ('blog', 27), ('docs', 45), ('blog', 26), ('home', 49), ('home', 44)]


def load_visits():
    """Yield the stored visits one at a time."""
    for page, minutes in ROWS:
        yield Visit(page, minutes)

