"""A ledger of visits."""


class VisitLedger:
    def __init__(self, visits=()):
        self._visits = list(visits)

    def visits(self):
        """Return the visits held (a copy, so callers cannot change the ledger)."""
        return list(self._visits)

    def add(self, visit):
        """Add one visit to the ledger."""
        self.visits().append(visit)

    def total(self):
        """Return the total minutes of the visits held."""
        return sum(x.minutes for x in self._visits)


def largest_minutes(visits):
    """Return the largest minutes, or None when there are no visits."""
    values = [x.minutes for x in visits]
    return max(values) if values else None

